// CODE NODE: CLEAN INTERNAL DATA
// ===== KONFIGURASI NAMA KOLOM (ubah di sini bila nama kolom pada sheet/CSV Anda berbeda) =====
const KOL_TANGGAL   = ['Tanggal Transaksi', 'Tanggal', 'Date', 'Tgl'];
const KOL_NOMINAL   = ['Jumlah (IDR)', 'Jumlah', 'Nominal', 'Amount', 'Jumlah Transaksi'];
const KOL_DESKRIPSI = ['Deskripsi', 'Deskripsi Transaksi', 'Keterangan', 'Uraian', 'Description', 'Catatan'];
const KOL_ID        = ['ID Referensi', 'ID Transaksi Bank', 'ID Transaksi', 'Referensi', 'ID', 'No. Transaksi'];
// ==========================================================================================

const norm = s => String(s).replace(/^\uFEFF/, '').trim().toLowerCase();
const pad = n => String(n).padStart(2, '0');

// Ambil nilai kolom berdasarkan daftar kemungkinan nama (tidak peka huruf besar/kecil, spasi & BOM diabaikan)
function pick(row, candidates) {
  const map = {};
  Object.keys(row).forEach(k => { map[norm(k)] = k; });
  for (const c of candidates) {
    const k = map[norm(c)];
    if (k !== undefined) return { found: true, key: k, value: row[k] };
  }
  return { found: false, key: null, value: undefined };
}

// Standardisasi tanggal menjadi YYYY-MM-DD (format lokal Indonesia: DD/MM/YYYY)
function cleanDate(raw) {
  if (raw === null || raw === undefined || raw === '') return '';
  if (typeof raw === 'number' && raw > 20000 && raw < 80000) {          // nomor seri Excel/Sheets
    return new Date(Math.round((raw - 25569) * 86400 * 1000)).toISOString().slice(0, 10);
  }
  const s = String(raw).trim();
  const iso = s.match(/^(\d{4})[-\/.](\d{1,2})[-\/.](\d{1,2})/);        // YYYY-MM-DD
  if (iso) return `${iso[1]}-${pad(iso[2])}-${pad(iso[3])}`;
  const dmy = s.match(/^(\d{1,2})[-\/.](\d{1,2})[-\/.](\d{2,4})/);      // DD/MM/YYYY
  if (dmy) {
    const y = dmy[3].length === 2 ? '20' + dmy[3] : dmy[3];
    return `${y}-${pad(dmy[2])}-${pad(dmy[1])}`;
  }
  return '';
}

// Hapus semua karakter non-angka (Rp, titik, koma, spasi) -> angka murni
function cleanAmount(raw) {
  if (raw === null || raw === undefined || raw === '') return null;
  let s = String(raw).trim();
  s = s.replace(/[.,]\d{1,2}$/, '');          // buang desimal di ujung, mis. ",00" atau ".50"
  const digits = s.replace(/\D/g, '');
  return digits === '' ? null : parseInt(digits, 10);
}
// Tipe transaksi yang diproses (kolom tipe boleh tidak ada; bila ada, baris lain dilewati)
const KOL_TIPE = ['Tipe Transaksi', 'Tipe', 'Jenis Transaksi'];
const TIPE_VALID = ['pembayaran', 'pengeluaran', 'penerimaan'];

const results = [];
const all = $input.all();

all.forEach((item, idx) => {
  const row = item.json;

  // 1. Filter tipe transaksi
  const tipe = pick(row, KOL_TIPE);
  if (tipe.found && String(tipe.value || '').trim() !== '' &&
      !TIPE_VALID.includes(String(tipe.value).trim().toLowerCase())) return;

  // 2. Standardisasi tanggal -> YYYY-MM-DD
  const tgl = pick(row, KOL_TANGGAL);
  const nom = pick(row, KOL_NOMINAL);
  if (idx === 0 && !tgl.found) throw new Error('Kolom tanggal tidak ditemukan. Kolom yang ada: ' + Object.keys(row).join(', '));
  if (idx === 0 && !nom.found) throw new Error('Kolom nominal tidak ditemukan. Kolom yang ada: ' + Object.keys(row).join(', '));

  const cleanedDate = cleanDate(tgl.value);
  // 3. Pembersihan nominal -> angka murni
  const cleanedAmount = cleanAmount(nom.value);

  // 4. match_key = tanggal_nominal (baris yang tidak valid diberi kunci unik agar tampil sebagai selisih)
  const valid = cleanedDate !== '' && cleanedAmount !== null;
  const match_key = valid ? `${cleanedDate}_${cleanedAmount}` : `TIDAK_VALID_INTERNAL_${idx + 2}`;

  results.push({ json: {
    sumber: 'INTERNAL',
    match_key,
    tanggal: cleanedDate,
    nominal: cleanedAmount,
    tipe: tipe.found ? String(tipe.value || '').trim() : '',
    deskripsi: String(pick(row, KOL_DESKRIPSI).value || '').trim(),
    referensi: String(pick(row, KOL_ID).value || '').trim(),
    baris_asal: idx + 2
  }});
});

return results;

// CODE NODE: CLEAN BANK DATA
// ===== KONFIGURASI NAMA KOLOM (ubah di sini bila nama kolom pada sheet/CSV Anda berbeda) =====
const KOL_TANGGAL   = ['Tanggal Bank', 'Tanggal', 'Tanggal Transaksi', 'Date', 'Tgl'];
