const KOL_DESKRIPSI = ['Deskripsi', 'Deskripsi Transaksi', 'Keterangan', 'Uraian', 'Description', 'Catatan'];
const KOL_ID        = ['ID Referensi', 'ID Transaksi Bank', 'ID Transaksi', 'Referensi', 'ID', 'No. Transaksi'];
// ==========================================================================================

