}
const results = [];
const all = $input.all();

all.forEach((item, idx) => {
  const row = item.json;

  // 1. Standardisasi tanggal bank -> YYYY-MM-DD
  const tgl = pick(row, KOL_TANGGAL);
  const nom = pick(row, KOL_NOMINAL);
  if (idx === 0 && !tgl.found) throw new Error('Kolom tanggal bank tidak ditemukan. Kolom yang ada: ' + Object.keys(row).join(', '));
  if (idx === 0 && !nom.found) throw new Error('Kolom nominal bank tidak ditemukan. Kolom yang ada: ' + Object.keys(row).join(', '));

  const cleanedDate = cleanDate(tgl.value);
  // 2. Hapus pemisah ribuan & karakter non-angka
  const cleanedAmount = cleanAmount(nom.value);

  // 3. match_key identik dengan data internal
  const valid = cleanedDate !== '' && cleanedAmount !== null;
  const match_key = valid ? `${cleanedDate}_${cleanedAmount}` : `TIDAK_VALID_BANK_${idx + 2}`;

  results.push({ json: {
    sumber: 'BANK',
    match_key,
    tanggal: cleanedDate,
    nominal: cleanedAmount,
    tipe: '',
    deskripsi: String(pick(row, KOL_DESKRIPSI).value || '').trim(),
    referensi: String(pick(row, KOL_ID).value || '').trim(),
    baris_asal: idx + 2
  }});
});

return results;

// CODE NODE: ANALISA REKONSILIASI
// Status: MATCHED | MISSING IN BANK (ada di internal, tidak ada di bank) | UNRECORDED INTERNAL (ada di bank, tidak ada di internal)
const items = $input.all();

// 1. Kelompokkan berdasarkan match_key
const grouped = {};
for (const item of items) {
  const j = item.json;
  if (!grouped[j.match_key]) grouped[j.match_key] = { INTERNAL: [], BANK: [] };
  grouped[j.match_key][j.sumber].push(j);
}

// 2. Tentukan status. Bila satu kunci muncul beberapa kali, dipasangkan satu-satu;
//    sisa di salah satu sisi dianggap selisih.
const results = [];
for (const key of Object.keys(grouped)) {
  const internal = grouped[key].INTERNAL;
  const bank = grouped[key].BANK;
  const pairs = Math.min(internal.length, bank.length);

  for (let i = 0; i < pairs; i++) {
    results.push({ Status: 'MATCHED', Prioritas: 'Low', Pesan: '✅ Data klop (Cocok).',
      Tanggal: internal[i].tanggal, Nominal: internal[i].nominal, match_key: key,
      Ref_Internal: internal[i].referensi || 'N/A', Ref_Bank: bank[i].referensi || 'N/A',
      Deskripsi: internal[i].deskripsi || bank[i].deskripsi || '-',
      Deskripsi_Internal: internal[i].deskripsi, Deskripsi_Bank: bank[i].deskripsi,
      Baris_Internal: internal[i].baris_asal, Baris_Bank: bank[i].baris_asal });
  }
  for (let i = pairs; i < internal.length; i++) {
    results.push({ Status: 'MISSING IN BANK', Prioritas: 'High', Pesan: '⚠️ Tercatat di Internal, tapi tidak ada di Bank.',
      Tanggal: internal[i].tanggal, Nominal: internal[i].nominal, match_key: key,
      Ref_Internal: internal[i].referensi || 'N/A', Ref_Bank: 'N/A',
      Deskripsi: internal[i].deskripsi || '-',
      Deskripsi_Internal: internal[i].deskripsi, Deskripsi_Bank: '',
      Baris_Internal: internal[i].baris_asal, Baris_Bank: '' });
  }
  for (let i = pairs; i < bank.length; i++) {
    results.push({ Status: 'UNRECORDED INTERNAL', Prioritas: 'Medium', Pesan: '⚠️ Ada di Bank, tapi tidak tercatat di Internal.',
      Tanggal: bank[i].tanggal, Nominal: bank[i].nominal, match_key: key,
      Ref_Internal: 'N/A', Ref_Bank: bank[i].referensi || 'N/A',
      Deskripsi: bank[i].deskripsi || '-',
      Deskripsi_Internal: '', Deskripsi_Bank: bank[i].deskripsi,
      Baris_Internal: '', Baris_Bank: bank[i].baris_asal });
  }
}

// 3. Urutkan: selisih lebih dulu, lalu berdasarkan tanggal
const urutan = { 'MISSING IN BANK': 0, 'UNRECORDED INTERNAL': 1, 'MATCHED': 2 };
results.sort((a, b) => (urutan[a.Status] - urutan[b.Status]) || String(a.Tanggal).localeCompare(String(b.Tanggal)));

return results.map(r => ({ json: r }));

// CODE NODE: SUSUN PESAN SELISIH (hanya menerima transaksi yang TIDAK COCOK dari node Cek Status Match)
const bad = $input.all().map(i => i.json);

// Ambil seluruh hasil analisa untuk ringkasan (termasuk yang MATCHED)
let semua = bad;
try { semua = $('Analisa Status').all().map(i => i.json); } catch (e) {}

const rp = n => 'Rp' + String(Math.round(n || 0)).replace(/\B(?=(\d{3})+(?!\d))/g, '.');
const jumlah = (arr) => arr.reduce((s, r) => s + (Number(r.Nominal) || 0), 0);

const matched   = semua.filter(r => r.Status === 'MATCHED');
const missing   = bad.filter(r => r.Status === 'MISSING IN BANK');
const unrecord  = bad.filter(r => r.Status === 'UNRECORDED INTERNAL');

let waktu;
try { waktu = new Date().toLocaleString('id-ID', { timeZone: 'Asia/Jakarta', dateStyle: 'long', timeStyle: 'short' }); }
catch (e) { waktu = new Date().toISOString(); }

const selisih = jumlah(missing) - jumlah(unrecord); // total internal - total bank (untuk transaksi yang tidak cocok)

const header = [
  '🚨 LAPORAN REKONSILIASI - ADA SELISIH',
  `🕒 ${waktu}`,
  '',
  `✅ Matched: ${matched.length} transaksi`,
  `❗ Missing in Bank: ${missing.length} transaksi (${rp(jumlah(missing))})`,
  `❗ Unrecorded Internal: ${unrecord.length} transaksi (${rp(jumlah(unrecord))})`,
  `📉 Selisih (Internal - Bank): ${selisih < 0 ? '-' : ''}${rp(Math.abs(selisih))}`,
].join('\n');

const baris = [];
const tulis = (judul, arr, kolRef) => {
  if (!arr.length) return;
  baris.push('', judul);
  arr.forEach((r, i) => baris.push(`${i + 1}. ${r.Tanggal || '-'} | ${rp(r.Nominal)} | ${r[kolRef]} | ${r.Deskripsi || '-'}`));
};
tulis('--- MISSING IN BANK (ada di internal, tidak ada di bank) ---', missing, 'Ref_Internal');
tulis('--- UNRECORDED INTERNAL (ada di bank, tidak ada di internal) ---', unrecord, 'Ref_Bank');

// Pecah menjadi beberapa pesan bila melebihi batas Telegram (4096 karakter)
const BATAS = 3500;
const potongan = [];
let sekarang = header;
for (const ln of baris) {
  if ((sekarang + '\n' + ln).length > BATAS) { potongan.push(sekarang); sekarang = '(lanjutan)'; }
  sekarang += '\n' + ln;
}
potongan.push(sekarang);

return potongan.map((text, i) => ({ json: { text, bagian: i + 1, dari: potongan.length } }));
